From 6a6de671c6af235c3f9af308f85044d88296628b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:46:32 +0100
Subject: [PATCH] applets/pager: let windows be raised from the desktop tooltip

Each desktop's tooltip listed its windows as plain text and closed once
the pointer moved onto it. Make it interactive and show every window as
an entry with its icon that activates that window when clicked.

BUG: 368659
---
 applets/pager/pagermodel.cpp |   5 ++
 applets/pager/pagermodel.h   |   1 +
 applets/pager/qml/main.qml   | 169 ++++++++++++++++++++++-------------
 3 files changed, 115 insertions(+), 60 deletions(-)

diff --git a/applets/pager/pagermodel.cpp b/applets/pager/pagermodel.cpp
index 6e476f3d15..7db5db6e3a 100644
--- a/applets/pager/pagermodel.cpp
+++ b/applets/pager/pagermodel.cpp
@@ -483,6 +483,11 @@ void PagerModel::moveWindow(const QModelIndex &index,
     }
 }

+void PagerModel::activateWindow(const QModelIndex &index)
+{
+    d->tasksModel->requestActivate(static_cast<const WindowModel *>(index.model())->mapToSource(index));
+}
+
 void PagerModel::changePage(int page)
 {
     if (currentPage() == page) {
diff --git a/applets/pager/pagermodel.h b/applets/pager/pagermodel.h
index 02613b42dc..fa48f1e1af 100644
--- a/applets/pager/pagermodel.h
+++ b/applets/pager/pagermodel.h
@@ -87,6 +87,7 @@ public:
                                 const QVariant &sourceItemId,
                                 qreal widthScaleFactor,
                                 qreal heightScaleFactor);
+    Q_INVOKABLE void activateWindow(const QModelIndex &window);
     Q_INVOKABLE void changePage(int page);
     Q_INVOKABLE void drop(QMimeData *mimeData, int modifiers, const QVariant &itemId);
     Q_INVOKABLE void addDesktop();
diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..a908fdc468 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -61,33 +61,70 @@ PlasmoidItem {
     readonly property color windowInactiveColor: colorWithAlpha(Kirigami.Theme.textColor, 0.17)
     readonly property color windowInactiveBorderColor: colorWithAlpha(Kirigami.Theme.textColor, 0.5)

-    function sanitize(input: string): string {
-        // Based on QQuickStyledTextPrivate::parseEntity
-        const table = {
-            '>': '&gt;',
-            '<': '&lt;',
-            '&': '&amp;',
-            "'": '&apos;',
-            '"': '&quot;',
-            '\u00a0': '&nbsp;',
-        };
-        return input.replace(/[<>&'"\u00a0]/g, c => table[c]);
-    }
+    component WindowList: ColumnLayout {
+        id: windowList
+
+        required property string title
+        required property var windows

-    function generateWindowList(windows) {
         // if we have 5 windows, we would show "4 and another one" with the
         // hint that there's 1 more taking the same amount of space than just showing it
-        const maximum = windows.length === 5 ? 5 : 4
+        readonly property int maximum: windows.length === 5 ? 5 : 4
+
+        signal windowClicked(var window)

-        let text = "<ul><li>"
-            + windows.slice(0, maximum).map(sanitize).join("</li><li>")
-            + "</li></ul>";
+        spacing: 0
+        visible: windows.length > 0

-        if (windows.length > maximum) {
-            text += i18ncp("@info:tooltip overflow label", "…and %1 other window", "…and %1 other windows", windows.length - maximum)
+        PlasmaComponents3.Label {
+            Layout.fillWidth: true
+            text: windowList.title
+            textFormat: Text.PlainText
+            elide: Text.ElideRight
+            opacity: 0.75
+            visible: text !== ""
         }

-        return text
+        Repeater {
+            model: windowList.windows.slice(0, windowList.maximum)
+
+            PlasmaComponents3.ItemDelegate {
+                id: windowEntry
+
+                required property var modelData
+
+                Layout.fillWidth: true
+                text: modelData.display
+
+                contentItem: RowLayout {
+                    spacing: Kirigami.Units.smallSpacing
+
+                    Kirigami.Icon {
+                        Layout.preferredWidth: Kirigami.Units.iconSizes.small
+                        Layout.preferredHeight: Kirigami.Units.iconSizes.small
+                        source: windowEntry.modelData.decoration ?? undefined
+                        animated: false
+                    }
+
+                    PlasmaComponents3.Label {
+                        Layout.fillWidth: true
+                        text: windowEntry.text
+                        textFormat: Text.PlainText
+                        elide: Text.ElideRight
+                    }
+                }
+
+                onClicked: windowList.windowClicked(modelData)
+            }
+        }
+
+        PlasmaComponents3.Label {
+            Layout.fillWidth: true
+            text: i18ncp("@info:tooltip overflow label", "…and %1 other window", "…and %1 other windows", windowList.windows.length - windowList.maximum)
+            textFormat: Text.PlainText
+            opacity: 0.75
+            visible: windowList.windows.length > windowList.maximum
+        }
     }

     MouseArea {
@@ -324,57 +361,69 @@ PlasmoidItem {
             delegate: DesktopDelegate {
                 id: desktop

-                mainText: display
-                // our ToolTip has maximumLineCount of 8 which doesn't fit but QML doesn't
-                // respect that in RichText so we effectively can put in as much as we like :)
-                // it also gives us more flexibility when it comes to styling the <li>
-                textFormat: Text.RichText
+                property var visibleWindows: []
+                property var minimizedWindows: []

-                function updateSubTextIfNeeded() {
+                interactive: true
+                mainItem: Item {
+                    implicitWidth: toolTipLayout.width + Kirigami.Units.largeSpacing * 2
+                    implicitHeight: toolTipLayout.implicitHeight + Kirigami.Units.largeSpacing * 2
+
+                    ColumnLayout {
+                        id: toolTipLayout
+
+                        anchors.centerIn: parent
+                        width: Math.min(implicitWidth, Kirigami.Units.gridUnit * 20)
+                        spacing: Kirigami.Units.smallSpacing
+
+                        Kirigami.Heading {
+                            Layout.fillWidth: true
+                            level: 3
+                            text: desktop.display
+                            textFormat: Text.PlainText
+                            elide: Text.ElideRight
+                        }
+
+                        WindowList {
+                            title: desktop.visibleWindows.length > 1 ? i18ncp("@info:tooltip start of list", "%1 Window:", "%1 Windows:", desktop.visibleWindows.length) : ""
+                            windows: desktop.visibleWindows
+                            onWindowClicked: window => desktop.activateWindow(window)
+                        }
+
+                        WindowList {
+                            title: i18ncp("@info:tooltip", "%1 Minimized Window:", "%1 Minimized Windows:", desktop.minimizedWindows.length)
+                            windows: desktop.minimizedWindows
+                            onWindowClicked: window => desktop.activateWindow(window)
+                        }
+                    }
+                }
+
+                function activateWindow(window: Item): void {
+                    pagerModel.activateWindow(tasksModel.index((window as WindowDelegate).index, 0));
+                    hideImmediately();
+                }
+
+                function updateWindowListsIfNeeded() {
                     if (!containsMouse) {
                         return;
                     }

-                    let text = ""
-                    let visibleWindows = []
-                    let minimizedWindows = []
+                    let visible = []
+                    let minimized = []

                     for (let i = 0, length = windowRectRepeater.count; i < length; ++i) {
                         const window = windowRectRepeater.itemAt(i) as WindowDelegate
                         if (window) {
                             if (window.minimized) {
-                                minimizedWindows.push(window.display)
+                                minimized.push(window)
                             } else {
-                                visibleWindows.push(window.display)
+                                visible.push(window)
                             }
                         }
                     }

-                    if (visibleWindows.length === 1) {
-                        text += visibleWindows[0]
-                    } else if (visibleWindows.length > 1) {
-                        text += i18ncp("@info:tooltip start of list", "%1 Window:", "%1 Windows:", visibleWindows.length)
-                            + root.generateWindowList(visibleWindows)
-                    }
-
-                    if (visibleWindows.length && minimizedWindows.length) {
-                        if (visibleWindows.length === 1) {
-                            text += "<br>"
-                        }
-                        text += "<br>"
-                    }
-
-                    if (minimizedWindows.length > 0) {
-                        text += i18ncp("@info:tooltip", "%1 Minimized Window:", "%1 Minimized Windows:", minimizedWindows.length)
-                            + root.generateWindowList(minimizedWindows)
-                    }
-
-                    if (text.length) {
-                        // Get rid of the spacing <ul> would cause
-                        text = "<style>ul { margin: 0; }</style>" + text
-                    }
-
-                    subText = text
+                    visibleWindows = visible
+                    minimizedWindows = minimized
                 }

                 width: pagerItemGrid.columnWidth
@@ -470,7 +519,7 @@ PlasmoidItem {

                         model: desktop.tasksModel

-                        onCountChanged: desktop.updateSubTextIfNeeded()
+                        onCountChanged: desktop.updateWindowListsIfNeeded()

                         component WindowDelegate: Rectangle {
                             required property string display
@@ -488,8 +537,8 @@ PlasmoidItem {
                         delegate: WindowDelegate {
                             id: windowRect

-                            onMinimizedChanged: desktop.updateSubTextIfNeeded()
-                            onDisplayChanged: desktop.updateSubTextIfNeeded()
+                            onMinimizedChanged: desktop.updateWindowListsIfNeeded()
+                            onDisplayChanged: desktop.updateWindowListsIfNeeded()

                             z: 1 + stackingOrder
                             /* since we move clipRect with 1, move it back */
@@ -591,7 +640,7 @@ PlasmoidItem {
                     }
                 }

-                onContainsMouseChanged: updateSubTextIfNeeded()
+                onContainsMouseChanged: updateWindowListsIfNeeded()
             }
         }
     }
-- 
2.53.0
